Body:
I have this same problem with qml files

```jsonc
{
  "$schema": "https://opencode.ai/config.json",
  "model": "llamacpp/sysadmin-qwen-3-6",
  "autoupdate": true,
  "provider": {

    "llamacpp": {
      "npm": "@ai-sdk/openai-compatible",
      "options": {
        "baseURL": "http://localhost:11435/v1"
      },
      "models": {
        "sysadmin-qwen-3-6": {
          "name": "Qwen 3.6 27B (ik_llama)",
          "tool_call": true,
          "supports_thinking": true
        }
      }
    },
  },
  "lsp": {
    "qml": {
      "command": [
        "qmlls",
        "-I",
        "/etc/xdg/quickshell/noctalia-shell"
      ],
      "extensions": [
        "qml"
      ]
    }
  }
