```

This nodejs script returns 49 diagnostics

```js
const { spawn } = require('child_process');
const fs = require('fs');

const lsp = spawn('qmlls', ['-I', '/etc/xdg/quickshell/noctalia-shell']);
let diags = [];

const FILEPATH = '/path/to/Settings.qml';
const ROOTPATH = '/path/';

lsp.stdout.on('data', (data) => {
  const parts = data.toString().split('\r\n\r\n');
  for (let i = 1; i < parts.length; i+=2) {
    try {
      const msg = JSON.parse(parts[i]);
      if (msg.method === 'textDocument/publishDiagnostics') {
        diags = msg.params.diagnostics;
      }
    } catch(e) {}
  }
});

const init = { jsonrpc: '2.0', id: 1, method: 'initialize', params: { capabilities: {}, rootUri: `file://${ROOTPATH}` }};

lsp.stdin.write('Content-Length: ' + Buffer.from(JSON.stringify(init)).length + '\r\n\r\n' + JSON.stringify(init));

setTimeout(() => {
  const file = fs.readFileSync(FILEPATH, 'utf8');
  const open = {
    jsonrpc: '2.0',
    method: 'textDocument/didOpen',
    params: { textDocument: { uri: `file://${FILEPATH}`, languageId: 'qml', version: 1, text: file }}
  };
  lsp.stdin.write('Content-Length: ' + Buffer.from(JSON.stringify(open)).length + '\r\n\r\n' + JSON.stringify(open));
}, 500);

setTimeout(() => {
  console.log('Diagnostics count:', diags.length);
  diags.forEach(d => console.log('  Line', d.range.start.line + 1, ':', d.message));
  lsp.kill();
}, 2000);
```

